SELECT song.*, source.source_type, source.location, source.username, source.password_encrypted, remote.song_id AS remote_resource_id, remote.identity_size, remote.identity_modified, remote.etag AS content_etag, remote.binding AS remote_binding, remote.generation AS remote_generation, doc.document_json AS formal_audio_json, loc.source_id AS location_source_id, loc.relative_path AS location_path, loc.state AS location_state, loc.observation_json AS location_observation, shared.verification AS shared_verification, claim.claim_json
FROM media_song song JOIN media_source source ON source.id=song.source_id
LEFT JOIN webdav_resource remote ON remote.song_id=song.id AND remote.archived_at IS NULL LEFT JOIN metadata_document doc ON doc.id=song.id LEFT JOIN metadata_location loc ON loc.media_id=song.id LEFT JOIN media_shared_song shared ON shared.song_id=song.id
LEFT JOIN media_audio_import claim ON claim.song_id=song.id ORDER BY song.id
